def test_fix_dates(helpers, auto_fake_fixdate_finder):
    workspace = helpers.provider_workspace_helper(name=Provider.name())
    parser = Parser(ws=workspace)
    entry = {
        "id": "ALSA-2019:3706",
        "published": "2019-11-26T23:30:00-05:00",
        "affected": [
            {
                "package": {"ecosystem": "AlmaLinux:8", "name": "lua"},
                "ranges": [{"type": "ECOSYSTEM", "events": [{"introduced": "0"}, {"fixed": "5.3.4-11.el8"}]}],
            }
        ],
    }
    _, _, record = parser._normalize(entry, "8")
    assert [a["package"]["name"] for a in record["affected"]] == ["lua", "lua-libs"]
    for a in record["affected"]:
        assert a["ranges"][0]["database_specific"]["anchore"]["fixes"] == [
            {"version": "5.3.4-11.el8", "date": "2019-11-27", "kind": "advisory"}
        ]
    assert record["database_specific"]["anchore"] == {"record_type": "advisory"}
